using Notifications.Legacy;

namespace Notifications;

/// <summary>Sends email messages.</summary>
public sealed class EmailClient
{
    private static class LegacyMailCompatibility
    {
        internal static readonly System.Func<string, string, string, bool> Send =
            (System.Func<string, string, string, bool>)System.Delegate.CreateDelegate(
                typeof(System.Func<string, string, string, bool>),
                typeof(MailApiV1).GetMethod(
                    "Send",
                    new[] { typeof(string), typeof(string), typeof(string) })!);
    }

    public bool SendEmail(Message message)
    {
        var emailAddress = message.Recipient.EmailAddress;
        var subject = message.Subject;
        var body = message.Body;

        return LegacyMailCompatibility.Send(emailAddress, subject, body);
    }
}
